select ok(has_function_privilege('authenticated','public.import_timer_snapshot(jsonb)','EXECUTE'),'authenticated RPC');
select ok(not has_function_privilege('anon','public.import_timer_snapshot(jsonb)','EXECUTE'),'anonymous RPC blocked');
select ok(not has_table_privilege('authenticated','public.timer_imports','INSERT'),'receipt direct insert blocked');
select ok(not has_table_privilege('authenticated','public.timer_import_sessions','UPDATE'),'mapping direct update blocked');
select ok(not has_table_privilege('authenticated','public.work_session_events','INSERT'),'event direct writes blocked');
select ok(not has_table_privilege('authenticated','public.work_session_time_adjustments','INSERT'),'adjustment direct writes blocked');
set local role authenticated;
set local request.jwt.claim.sub='dddddddd-3d22-4000-8000-000000000001';
select throws_ok($$select public.import_timer_snapshot(current_setting('test.timer')::jsonb)$$,'P0002',null,'counter receipt required');
select set_config('test.counterresult',public.import_counter_snapshot(current_setting('test.counter')::jsonb)::text,true);
select set_config('test.result',public.import_timer_snapshot(current_setting('test.timer')::jsonb)::text,true);
select is(current_setting('test.result')::jsonb->>'status','imported','import succeeds');
select is((select count(*) from public.work_sessions),1::bigint,'one ended session');
select is((select count(*) from public.work_sessions where status<>'ended'),0::bigint,'does not activate session');
select is((select accumulated_ms from public.work_sessions),3600000::bigint,'original duration preserved');
select is((select count(*) from public.work_session_events),4::bigint,'all transitions preserved');
select is((select event_type from public.work_session_events where revision_after=2),'pause','pause event preserved');
select is((select effective_at from public.work_session_events where revision_after=1),'2026-10-22T14:40:00Z'::timestamptz,'historical start preserved');
select is((select count(*) from public.work_session_time_adjustments),2::bigint,'all corrections imported');
select is((select previous_adjusted_ms from public.work_session_time_adjustments where adjustment_revision=2),7200000::bigint,'audit chain preserved');
select is((select adjusted_ms from public.work_session_time_adjustments where adjustment_revision=2),5400000::bigint,'last effective time preserved');
select is((select reason from public.work_session_time_adjustments where adjustment_revision=1),'블로킹 후 기록 정정','reason preserved');
select is((select created_at from public.work_session_time_adjustments where adjustment_revision=1),'2026-10-23T05:00:00Z'::timestamptz,'audit occurrence preserved');
select is((select source_local_adjustment_id::text from public.work_session_time_adjustments where adjustment_revision=1),current_setting('test.timer')::jsonb->'sessions'->0->'adjustments'->0->>'adjustmentId','source adjustment mapping');
select is(public.import_timer_snapshot(current_setting('test.timer')::jsonb)->>'status','duplicate','same ID idempotent');
select is(public.import_timer_snapshot(jsonb_set(current_setting('test.timer')::jsonb,'{importId}',to_jsonb(gen_random_uuid())))->>'status','imported','new batch reuses mapped source');
select is((select count(*) from public.work_sessions),1::bigint,'new batch cannot duplicate sessions');
select is((select count(*) from public.timer_import_sessions),1::bigint,'one source mapping');
select is((public.get_work_time_statistics()->'works'->0->>'savedMs')::bigint,5400000::bigint,'statistics use latest correction once');
select is((public.get_work_time_statistics('Asia/Seoul',null,null,0,'2026-10-22')->'works'->0->>'todaySavedMs')::bigint,1800000::bigint,'Seoul pre-midnight proportional share');
select is((public.get_work_time_statistics('Asia/Seoul',null,null,0,'2026-10-23')->'works'->0->>'todaySavedMs')::bigint,3600000::bigint,'Seoul post-midnight proportional share');
select throws_ok($$select public.import_timer_snapshot(jsonb_set(current_setting('test.timer')::jsonb,'{sessions,0,state,accumulatedMs}','0'))$$,'22023',null,'same import different payload rejected');
select throws_ok($$select public.import_timer_snapshot(jsonb_set(jsonb_set(current_setting('test.timer')::jsonb,'{importId}',to_jsonb(gen_random_uuid())),'{sessions,0,adjustments,1,adjustedMs}','0'))$$,'22023',null,'source audit cannot be silently changed after import');
set local request.jwt.claim.sub='dddddddd-3d22-4000-8000-000000000002';
select is((select count(*) from public.timer_imports),0::bigint,'other user receipts hidden');
select is((select count(*) from public.timer_import_sessions),0::bigint,'other user mappings hidden');
select is((select count(*) from public.work_sessions),0::bigint,'other user sessions hidden');
select throws_ok($$select public.import_timer_snapshot(current_setting('test.timer')::jsonb)$$,'P0002',null,'cannot attach to other user work');
select lives_ok($$select public.import_counter_snapshot(current_setting('test.counter')::jsonb)$$,'independent counter import contract remains unchanged');
select throws_ok($$select public.import_timer_snapshot(current_setting('test.timer')::jsonb)$$,'23505',null,'same device session cannot move to a second account');
set local request.jwt.claim.sub='';
select throws_ok($$select public.import_timer_snapshot(current_setting('test.timer')::jsonb)$$,'28000',null,'authentication required');
reset role;
select throws_ok('update public.timer_imports set local_work_item_id=gen_random_uuid()','23514',null,'receipts append only');
select throws_ok('delete from public.timer_import_sessions','23514',null,'source mappings append only');
select * from finish();rollback;
